"""Build the 010 visual review room; screenshots are captured from exact worktrees."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
room=ROOT/'docs/world-010-review'
room.mkdir(exist_ok=True)
(room/'index.html').write_text('''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>TOHEŞAR — World 010 / Visual Review</title><style>
*{box-sizing:border-box}body{margin:0;background:#e8e5e0;color:#35323d;font:14px/1.85 Arial,sans-serif}header,main,footer{max-width:1500px;margin:auto;padding:35px clamp(20px,4vw,60px)}header{border-bottom:1px solid #b5abba}h1{font:italic 400 clamp(42px,6vw,80px)/1.08 Georgia,serif;letter-spacing:-.04em;margin:25px 0}h2{font:400 28px/1.3 Georgia,serif;margin:0 0 14px}p{max-width:80ch}a{color:inherit;text-underline-offset:4px}nav{display:flex;gap:22px;flex-wrap:wrap}label{display:inline-flex;gap:10px;align-items:center;margin:20px 25px 0 0}select{padding:10px;background:#f3f0ed;border:1px solid #93849f;font:inherit;max-width:100%}section{margin:25px 0 60px;padding-top:25px;border-top:1px solid #b5abba}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0;min-width:0}img{display:block;width:100%;height:auto;background:#d4ccdb}figcaption{margin:12px 0;font-size:11px;overflow-wrap:anywhere}.solo{max-width:900px}.poses{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.tag{font:10px/1.6 Arial;letter-spacing:.12em}code{overflow-wrap:anywhere}.note{background:#d9d3e0;padding:20px 25px}.fallback{font-size:12px}@media(max-width:650px){.pair{gap:10px}.poses{grid-template-columns:1fr}.poses figure{max-width:430px}header,main,footer{padding:25px 18px}label{display:flex;margin:15px 0}h2{font-size:24px}}
</style></head><body><header><span class="tag">TOHEŞAR / WORLD CONTINUITY 010</span><h1>The space<br>between stories.</h1><p>009의 작품을 보존하며 그 사이를 연결한 빌드. BEFORE는 수정하지 않은 원본 커밋 <code>500672342c158929b0e278a7cb1fb976a88781d6</code>의 실제 브라우저 렌더링입니다. 두 버전은 같은 엔진·뷰포트·배율 1·폰트/이미지 준비 조건에서 촬영했습니다.</p><p class="note">Chromium / Playwright WebKit 26.5의 화면 비교입니다. iPhone·iPad Safari 실기기, 실제 브라우저 툴바, 구형 iOS, 배터리·발열은 미검증입니다. 화면 크기 이름은 하드웨어 테스트를 뜻하지 않습니다.</p><nav><a href="/journal/">Journal</a><a href="/journal/issues/001/#miniature-passage">Miniature Passage</a><a href="/journal/911/#miniature-passage">911 속 Passage</a><a href="/journal/issues/001/">Issue 001</a><a href="/docs/WORLD_010_VISUAL_AUDIT.md">Visual audit</a></nav><label>Engine<select id="engine"><option value="webkit">Playwright WebKit</option><option value="chromium">Chromium</option></select></label><label>Viewport<select id="viewport"><option value="390">390 × 844</option><option value="430">430 × 932</option><option value="820">820 × 1180</option><option value="1180" selected>1180 × 820</option><option value="1366">1366 × 1024</option><option value="1440">1440 × 900</option></select></label><p class="fallback">이미지를 선택하면 원래 크기로 열립니다. 390 / 1180에는 Issue 대표 지면·관련 기사·Atelier와 새 Passage도 포함합니다.</p></header><main id="comparison"></main><footer><p>기존 009의 워드마크, 사진, 미니어처와 원고를 보존했습니다. 새 Passage는 009에 없으므로 전후 비교로 위장하지 않고 독립된 새 지면으로 표시합니다.</p><a href="verification/checks.json">010 검증 기록</a> · <a href="preservation.json">보존 기록</a></footer><script>
const scenes=[['cover-start','Cover / First presence','사진과 워드마크의 기존 진입 장면. 휴대폰 사진 구도는 유지하고 상단 Journal의 글자와 터치 영역을 개선했습니다.'],['cover-middle','Cover / The page opens','가로 화면의 실제 보이는 높이에 맞춘 사진 프레임. Journal 링크가 움직임 중간에도 사라지지 않습니다.'],['cover-end','Cover / The final frame','가로 사진 높이를 확대하고 한국어 제목의 비례를 조정했습니다. 세로 사진의 기존 계산은 유지합니다.'],['journal','Journal / A frontispiece','iPad 가로에서 사진·제목·출처를 한 화면에 담습니다. 기존 섹션 탐색 안에서 Issue 001을 노출합니다.'],['issue','Issue 001 / The opening','009의 재킷과 편집 구도를 유지했습니다.'],['curve','911 / Curves','기존 사진 프레임과 곡선을 보존하고 챕터 끝에서 다음 지면을 선택할 수 있게 했습니다.'],['edge','F40 / Function','기존 수평 사진과 기능적 타이포그래피를 보존합니다.'],['proportion','Giulia / Proportion','009의 세이지 관찰 지면을 보존합니다.'],['language','Type 01 / A long horizon','긴 GT의 제조사 사진과 출처를 보존합니다. 이어지는 작은 세계는 이 챕터와 Atelier 사이에 놓입니다.'],['small','Miniature Atelier / Original plate','009의 세 대 구성은 그대로 보존합니다. Passage는 별도 지면입니다.'],['related','The next story','텍스트 목록에서 사진과 편집적 관계를 가진 다음 이야기로. 출처와 실제 URL을 함께 유지합니다.'],['atelier','Miniature Atelier / The room','기존 아틀리에 첫 장면은 보존했습니다.']];
const root=document.querySelector('#comparison'),engine=document.querySelector('#engine'),viewport=document.querySelector('#viewport');
function figure(file,label){return `<figure><a href="${file}"><img src="${file}" loading="lazy" alt="${label}"></a><figcaption>${label} / <a href="${file}">원본 크기</a></figcaption></figure>`}
function render(){const e=engine.value,w=viewport.value,full=['390','1180'].includes(w);root.innerHTML=scenes.filter((s,i)=>full||i<4).map(([key,title,note])=>`<section><h2>${title}</h2><p>${note}</p><div class="pair">${figure(`before/${e}-${w}-${key}.webp`,'BEFORE / 009')}${figure(`after/${e}-${w}-${key}.webp`,'AFTER / 010')}</div></section>`).join('');if(full)root.innerHTML+=`<section><span class="tag">NEW EDITORIAL SPREAD / NO 009 EQUIVALENT</span><h2>The Miniature Passage</h2><p>쿠페의 긴 곡선, 웨지의 빠른 수평 이동, GT의 느긋한 곡선. 같은 스크롤 진행률은 역방향에서도 같은 자세로 돌아옵니다. 자동차와 실제 탐색 링크는 분리했습니다.</p><div class="poses">${['first','middle','last'].map(n=>figure(`after/${e}-${w}-passage-${n}.webp`,'010 / '+n)).join('')}</div></section>`}
engine.addEventListener('change',render);viewport.addEventListener('change',render);render();
</script></body></html>''')
print('Built World 010 visual review room.')
